\begin{itemize}
    \item We will use the symbols ``$\lesssim$'' and ``$\gtrsim$'' to denote the inequality up to a multiplicative constant depending only on {\it a priori} data.
    \item We denote by $d_H(D,D')$ the Hausdorff distance between $D$ and $D'$, which is defined as follows,
    \begin{align*}
        d_H(D,D')=\max\left\lbrace \sup_{x\in D}{\rm dist}(x,D'),\; \sup_{x'\in D'}{\rm dist}(x',D) \right\rbrace.
    \end{align*}
 \end{itemize}

\label{th:main}
    Assume the geometrical and analytical conditions \zcref{assumption:geometric,assumption:singularity} hold. Let $u$ and $u'$ be solutions to \eqref{eq:calderon} with respect to $D$ and $D'$. We suppose that $\|\partial_\nu(u-u')\|_{H^{-1/2}(\Gamma_0)}\leq \varepsilon$ for $\varepsilon>0$ being sufficiently small. Then, there exists positive constants $\kappa$ and $C$ depending only on {\it a priori} data such that
    \begin{align}\label{eq:stable}
        d_H(D,D')\leq C \left(\ln|\ln \varepsilon|\right)^{-\kappa}.
    \end{align}

\label{th:SingDecom}
   Let $u$ be the solution to \eqref{eq:transmission}. Then, $u$ admits the following decomposition into vertex-singular part, edge-singular part and a regular part.
   \begin{align}\label{eq:SingDecom}
        u=\sum_{{\bf v}\;{\rm vertex}} u_{{\bf v}}+\sum_{E \;{\rm edge}} u_E+u_{\rm reg}.
    \end{align}

\label{assumption:singularity}
        Throughout the paper, we will assume that the following conditions hold.
    \begin{enumerate}
        \item  We follow case b) of Theorem 7.1 in \cite{Dauge1999}. That is, the parameter $s$ is chosen such that $s_0\leq s <s_0+1$ in order to have sufficient regularity for $u_{\rm reg}$ and to avoid the ``shadow terms'' in condition c) for singular functions. Furthermore, from the estimates of the first singularity exponents $\frac{1}{2}<\mu_1<1<\lambda_1$, we have $s_0=\mu_1>\frac{1}{2}$ and $s_0+1>\frac{3}{2}$. With this condition, we will choose $s$ close enough to $\mu_1+1$ such that,
        \begin{align*}
            \frac{3}{2}< s <\mu_1+1.
        \end{align*}
        As an immediate consequence, the regular part $u_{\rm reg}$ has at least $H^{5/2+\epsilon}$ regularity in each subdomain, where $\epsilon:=s-\frac{3}{2}>0$.
        \item There is no $\log$ terms in the vertex or edge singular expansions. That is, $K_{\bf v,\lambda}=K_{E,\mu}=0$ for any vertex $\bf v$ and any edge $E$.
        \item For any edge $E$, the first edge singularity is not degenerate, i.e., $\gamma_{E,\mu_1}$ is not identically null on $E$.
        \item For any adjacent vertex-edge pair $({\bf v}, E)$ the first interaction coefficient $a_{E,\mu_1}^{{\bf v},\lambda_1}$ in the asymptotic expansion \eqref{eq:asym-coef} is not zero.
    \end{enumerate}

Let $0<r_1<r_2<r_3$. There exists a constant $\widetilde{\alpha}\in (0,1)$ such that for any harmonic function $w\in H^1_{loc}(2.4^n)$ with $n\geq 2$, it holds that
        \begin{align*}
            \sup_{|x|\leq r_2}|w(x)|\leq \left(\sup_{|x|\leq r_1}|w(x)|\right)^{\widetilde{\alpha}}\left(\sup_{|x|\leq r_3}|w(x)|\right)^{1-\widetilde{\alpha}}.
        \end{align*}
        The exponent $\widetilde{\alpha}$ depends only on $n$ and the ratios $r_1/r_2$, $r_2/r_3$.

\label{prop:p1}
        Let $r>0$ and let $U\subset 2.4^3$ be a bounded and connected domain. Consider $x,y\in U$ and assume that there exists a rectifiable curve $\gamma$ in $U$ with endpoints $x$ and $y$ such that ${\rm dist}(\gamma,\partial U)>4r$. Consider also a bounded harmonic function $w$ in $U$. We assume furthermore that $w$ is bounded with $\|w\|_{L^\infty(B(x,r))}\leq 1$ and $\|w\|_{L^\infty(U)}= T>0$. Then, it holds that
        \begin{align*}
            \|w\|_{L^\infty(B(y,r))}\leq T \|w\|_{L^\infty(B(x,r))}^{\widetilde{\alpha}^{|\gamma|/r+1}},
        \end{align*}
        where $|\gamma|$ denotes the length of $\gamma$.

\label{prop:aa2}
        Let $U$ be a Lipschitz connected domain. Let $\Sigma\subset \partial U$ be an open portion of the boundary. Consider a harmonic function $w$ in $U$. We make the following assumptions 
        \begin{itemize}
            \item for any $y\in U$, there exists a rectifiable curve $\gamma$ in $U$ connecting $y$ and a point $x\in \Sigma$,
            \item the length of $\gamma$ is bounded by a uniform constant $L>0$,
            \item $\gamma$ does not touch the boundary of $U$ outside $\Sigma$, i.e., ${\rm dist}(\gamma,\partial U\setminus \Sigma)>4r$ for some $r>0$,
            \item $w$ is bounded with $\|w\|_{L^\infty(U)}=T>0$,
            \item $\|w\|_{H^{1/2}(\Sigma)}+\|\partial_{\nu} w\|_{H^{-1/2}(\Sigma)}\leq \varepsilon$ with $0< \varepsilon<1$.
        \end{itemize}
        Then, for all $y\in U$ and all sufficiently small $r>0$, one has
        \begin{align}\label{eq:propa-small-holder}
            |w(y)|\leq C T \varepsilon^{\widetilde{\alpha}^{L/r+1}},
        \end{align}
        with a constant $C$ depending only on {\it a priori} data.

\label{prop:propa-small}
        Let $u$ and $u'$ be solutions to \eqref{eq:calderon} corresponding to $D$ and $D'$, respectively. Let ${\bf v} \in \partial D$ be a vertex of $D$, and let $h>0$ satisfy $B({\bf v},h)\subset\Omega_{\delta_0}$ and $B({\bf v},h)\cap D'=\varnothing$. Then there exist $\alpha \in (0,1)$ and $T>0$, depending only on {\it a priori} data, such that for $0<\varepsilon<\varepsilon_m$,
        \begin{align*}
            \forall x\in B({\bf v},h)\setminus \overline{D},\quad & |(u-u')(x)|\leq T\left(\ln |\ln \varepsilon|\right)^{-\alpha};\\
            &|\nabla (u-u')(x)|\leq \frac{T}{{\rm dist}(x,\partial D)}\left(\ln |\ln \varepsilon|\right)^{-\alpha}.
        \end{align*}

\label{prop:int-identity}
            Let $u_0\in H^1_{loc}(2.4^3)$ be harmonic. Then
            \begin{align}\label{eq:int-id}
                (k-1)\int_{F_{\pm}}u_0\partial_\nu u d\sigma= &\int_{S^e \cup S^i\cup A_{\pm}} \left(u_0\partial_\nu (u-u')-(u-u')\partial_\nu u_0\right)d\sigma.
            \end{align}

\label{prop:lowerbound}
            The left-hand side of the integral identity \eqref{eq:int-id} admits the following decomposition:
            \begin{align*}
                &\int_{F_\pm} u_0\partial_\nu u d\sigma = I_{F,1} + I_{F,2,\infty}-I_{F,2,c} + I_{F,3} + I_{F,4} + I_{F,5}.
            \end{align*}
            Furthermore, for $\rho,h,h_z$ satisfying \eqref{eq:constraint1} and \eqref{eq:constraint2} and being sufficiently small, the following estimates hold for each term,
            \begin{align*}                
                &|I_{F,1}|\lesssim  \rho^{\lambda_1-1}h_z\tau^{-1}, &  &|I_{F,2,\infty}| \gtrsim \rho^{\lambda_1+\varepsilon_*-\mu_1} h_z \tau^{-\mu_1},\\
                &|I_{F,2,c}| \lesssim (\rho+h_z)^{1-\mu_1}\tau^{-\mu_1} e^{-\frac{\tau \widetilde{a} h}{2}}, &  &|I_{F,3}| \lesssim \rho^{-(s-\mu_1-1/2)}h_z \tau^{-(s-1/2)},\\
                &|I_{F,4}| \lesssim \rho^{-\widetilde{\mu_2}}h_z\tau^{-\widetilde{\mu_2}},&  &|I_{F,5}| \lesssim h_z\tau^{-1}.
            \end{align*}
            Here, $\varepsilon_*>0$ is a small constant, $\widetilde{\mu_2}=\mu_2$ if $s-\mu_2\geq 1/2$ and $\widetilde{\mu_2}=s-1/2$ if $s-\mu_2< 1/2$.

We split $u$ into singular and regular parts as stated in \zcref{th:SingDecom}. We mainly focus on the first edge singular function. More precisely, we decompose
            \begin{align*}
                u=u_{\bf v}+v_1+\widetilde{v_1}+u_{E,2}+u_{\rm reg},
            \end{align*}
            where 
            \begin{itemize}
                \item $u_{\bf v}$ is the vertex singular function associated with $\bf v$,
                \item $\displaystyle v_1(\widetilde{r},\theta,z):=\gamma_{E,\mu_1}(z)\widetilde{r}^{\mu_1}\varphi_{E,\mu_1}(\theta)$,
                \item $\displaystyle \widetilde{v_1}=(\mathcal{K}[\gamma_{E,\mu_1}](\widetilde{r},z)-\gamma_{E,\mu_1}(z))\widetilde{r}^{\mu_1}\varphi_{E,\mu_1}(\theta)$,
                \item $u_{E,2}$ is the remaining edge singular functions with the leading singular exponent $\mu_2$,
                \item $u_{\rm reg}$ is the regular part.
            \end{itemize}
            We also extend the rays $\Gamma_\pm$ to infinity and denote the corresponding faces by $F_\pm^\infty$. Straightforward computations give
            \begin{align*}
                \int_{F_\pm} u_0\partial_\nu u d\sigma = I_{F,1} + I_{F,2,\infty}-I_{F,2,c} + I_{F,3} + I_{F,4} + I_{F,5}.
            \end{align*}
            where
            \begin{align*}
                &I_{F,1} := \int_{F_{\pm}}u_0\partial_\nu u_{\bf v} d\sigma, & & I_{F,2,\infty} := \int_{F_{\pm}^\infty}u_0\partial_\nu v_1 d\sigma,\\
                &I_{F,2,c} := \int_{F_{\pm}^\infty\setminus F_{\pm}}u_0\partial_\nu v_1 d\sigma,& & I_{F,3} := \int_{F_{\pm}}u_0\partial_\nu \widetilde{v_1} d\sigma,\\
                &I_{F,4} := \int_{F_{\pm}}u_0\partial_\nu u_{E,2} d\sigma, & & I_{F,5} := \int_{F_{\pm}}u_0\partial_\nu u_{\rm reg} d\sigma.
            \end{align*}

            We first focus on the integral $I_{F,2,\infty}$. Since the variables are separated, we have
            \begin{align*}
                &\int_{F^\infty_\pm}u_0\partial_\nu v_1 d\sigma = \int_0^{h_z} \int_0^{+\infty} u_0(r,\pm \frac{a}{2},z)\partial_\nu v_1(r,\pm \frac{a}{2},z) dr dz,\\
                &= \int_0^{h_z} \gamma_{E,\mu_1}(z) \delta(z)^{-\mu_1}dz \left( \varphi'_{E,\mu_1}(\frac{a}{2}) \int_0^{+\infty}  r^{\mu_1-1} e^{z^+_a r} dr- \varphi'_{E,\mu_1}(-\frac{a}{2}) \int_0^{+\infty}  r^{\mu_1-1} e^{z^-_a r} dr \right).
            \end{align*}
            By construction of the CGO solution, $u_0(r,\pm \frac{a}{2},z) = e^{z^\pm_a r}$ with $z^\pm_a=-\tau e^{\mp i\frac{a}{2}}$. To evaluate the integral in $r$, we use a complex-analysis argument from Proposition 4.4 in \cite{moi5}. Thus,
            \begin{align*}
                \int_0^{+\infty}  r^{\mu_1-1} e^{z^{\pm}_a r} dr =\Gamma(\mu_1)(\frac{-1}{z^\pm_a})^{\mu_1};
            \end{align*}
            Here $\Gamma$ denotes Euler's Gamma function. Hence,
            \begin{align*}
                \left| \varphi'_{E,\mu_1}(\frac{a}{2}) \int_0^{+\infty}  r^{\mu_1-1} e^{z^+_a r} dr- \varphi'_{E,\mu_1}(-\frac{a}{2}) \int_0^{+\infty}  r^{\mu_1-1} e^{z^-_a r} dr \right| \geq \sin(a\mu_1)\Gamma(\mu_1)\tau^{-\mu_1}.
            \end{align*}
            We now estimate the integral with respect to $z$, $\displaystyle \int_0^{h_z} \gamma_{E,\mu_1}(z) \delta(z)^{-\mu_1}dz$. We use the assumptions 3.) and 4.) in \zcref{assumption:singularity} and the asymptotic behavior \eqref{eq:asym-coef} to derive that $\displaystyle \gamma_{E,\mu_1}(\rho) \sim a_{E,\mu_1}^{{\bf v},\lambda_k} \rho^{\lambda_k}$ as $\rho \to 0$. This asymptotic behavior implies that $\gamma_{E,\mu_1}(\rho)$ keeps the same sign as $\rho \rightarrow 0$, and we will assume that it is positive without loss of generality. By choosing $\varepsilon_*>0$, we have,
            \begin{align*}
                \frac{\gamma_{E,\mu_1}(\rho)}{\rho^{\lambda_1+\varepsilon_*}} \underset{{\rho}\rightarrow {0}}{\longrightarrow} +\infty.
            \end{align*}
            Consequently, there exists a constant $C_{\varepsilon_*}>0$ such that 
            \begin{align*}
                \forall 0<\rho<C_{\varepsilon_*},\quad \gamma_{E,\mu_1}(\rho) \geq  \rho^{\lambda_1+\varepsilon_*}.
            \end{align*} 
            We remark that $C_{\varepsilon_*}$ is a local constant, depending on the inclusion $D$, the edge $E$, the vertex $\bf v$, and the parameter $\varepsilon_*$.

            We also remark that the function $\delta$ is equivalent to the distance between the point under consideration and the vertex $\bf{v}$. Then there exist constants $C_\pm>0$, which depends only on the geometry and thus considered as an {\it a priori} parameter, such that for all $z\in (0,h_z)$,






            \begin{align}\label{eq:delta-eqv}
                C_- (\rho+z) \leq &\delta(z)\leq C_+ (\rho+z).
            \end{align}
            We assume hereafter that 
            \begin{align}\label{eq:constraint3}
                \rho+h_z<C_{\varepsilon_*},
            \end{align}     
            Hence,   
            \begin{align*}
                \left|\int_0^{h_z} \gamma_{E,\mu_1}(z) \delta(z)^{-\mu_1} dz \right| \geq \frac{C_+^{-\mu_1}}{\lambda_1+\varepsilon_*-\mu_1+1} \left((\rho+h_z)^{\lambda_1+\varepsilon_*-\mu_1+1}-\rho^{\lambda_1+\varepsilon_*-\mu_1+1}\right). 
            \end{align*}           
            We may choose $\varepsilon_*$ smaller than a certain {\it a priori} constant, so that
            \begin{align}\label{eq:esti-F2-infty}
                |I_{F,2,\infty}|=\left| \int_{F_\pm^\infty} u_0 \partial_\nu v_1 d\sigma \right| \gtrsim  h_z \rho^{\lambda_1+\varepsilon_*-\mu_1} \tau^{-\mu_1}.
            \end{align}

            Next, we consider the integral $I_{F,2,c}$ on the complementary faces. For $s,x >0$, we introduce the incomplete Gamma function
            \begin{align*}
                \Gamma(s,x)=\int_x^{+\infty} t^{s-1} e^{-t} dt.
            \end{align*}
            Using the inequality $\displaystyle e^{-t}\leq e^{-t/2}e^{-x/2}$ for $t\geq x$, we deduce that
            \begin{align*}
                \Gamma(s,x)\leq 2^s \Gamma(x) e^{-x/2}.
            \end{align*}
            Then, by a simple change of variables, we obtain
            \begin{align*}
                \left|\int_h^{+\infty} r^{\mu_1-1} e^{z_a^\pm r} dr \right|& \leq \int_h^{+\infty} r^{\mu_1-1} e^{-\tau \widetilde{a} r} dr\leq  (\tau \widetilde{a})^{-\mu_1} \Gamma(\mu_1, \tau \widetilde{a} h)\\
                &\leq (\tau \widetilde{a})^{-\mu_1} 2^{\mu_1} \Gamma(\mu_1) e^{-\frac{\tau \widetilde{a} h}{2}}.
            \end{align*}
            Applying the estimates of singular coefficients \eqref{eq:esti-edge-coef}, we deduce that
            \begin{align*}
                \left|\int_0^{h_z} \gamma_{E,\mu_1}\delta(z)^{-\mu_1}dz \right|&\leq C_+^{-\mu_1}\|\gamma_{E,\mu_1}\|_{L^2(E)} \frac{(\rho+h_z)^{1-\mu_1}-\rho^{1-\mu_1}}{1-\mu_1}\\
                &\leq C_+^{-\mu_1}C\|u\|_{H^1(\Omega)}\frac{(\rho+h_z)^{1-\mu_1}}{1-\mu_1}.
            \end{align*}
            Consequently,
            \begin{align}\label{eq:esti-F2-c}
                |I_{F,2,c}|&\leq 2\mu_1 (\tau \widetilde{a})^{-\mu_1} 2^{\mu_1} \Gamma(\mu_1) e^{-\frac{\tau \widetilde{a} h}{2}} C_+^{-\mu_1}C\|u\|_{H^1(\Omega)}\frac{(\rho+h_z)^{1-\mu_1}}{1-\mu_1}\nonumber\\
                &\lesssim \tau^{-\mu_1}(\rho+h_z)^{1-\mu_1}e^{-\frac{\tau \widetilde{a} h}{2}}.
            \end{align}

            Applying \zcref{lemma:K-gamma} and the estimates of singular coefficients \eqref{eq:esti-edge-coef}, we obtain
            \begin{align}\label{eq:esti-F3}
                |I_{F,3}|&\leq \int_0^{h_z}\int_0^h |\mathcal{K}[\gamma_{E,\mu_1}](r,z)-\gamma_{E,\mu_1}(z)| r^{\mu_1-1} e^{-\tau \widetilde{a} r} dr dz \nonumber\\
                & \leq C'_{\phi,\mu_1} \|\gamma_{E,\mu_1}\|_{V_{-s}^{s-\mu_1}(E)}\rho^{-(s-\mu_1-1/2)} \int_0^{h_z}\int_0^h r^{s-\mu_1-1/2+\mu_1-1} e^{-\tau \widetilde{a} r} dr dz \nonumber\\
                &\lesssim h_z \rho^{-(s-\mu_1-1/2)} \int_0^{+\infty} r^{s-3/2} e^{-\tau\widetilde{a} r} dr \nonumber\\
                & \lesssim h_z \rho^{-(s-\mu_1-1/2)} (\tau\widetilde{a})^{-(s-1/2)}\Gamma(s-1/2)\lesssim h_z \rho^{-(s-\mu_1-1/2)} \tau^{-(s-1/2)}.
            \end{align}

            The estimates of $I_{F,1}$, $I_{F,4}$, and $I_{F,5}$ are relatively straightforward. Consider a point $x=(r,\pm a/2, z)\in F_\pm$.
            \begin{itemize}
                \item It readily follows from the vertex singular functions and the estimates of singular coefficients that
            \begin{align*}
                |\nabla u_{\bf v}(x)| & \lesssim \rho^{\lambda_1-1}.
            \end{align*}
            We remark that $\lambda_1>1$.
            \item For the remaining edge singular functions, we apply \zcref{lemma:esti-grad-edge} and \eqref{eq:esti-edge-coef} to obtain
            \begin{align*}
                |\nabla u_{E,2}(x)| & \lesssim \frac{r^{\widetilde{\mu_2}-1}}{\rho^{\widetilde{\mu_2}}},
            \end{align*}
            where $\widetilde{\mu_2}=\mu_2$ if $s-\mu_2\geq 1/2$ and $\widetilde{\mu_2}=s-1/2$ if $s-\mu_2< 1/2$.
            \item Combining the Sobolev embedding $H^{3/2}\hookrightarrow L^\infty$ in $2.4^3$ with \eqref{eq:esti-reg-cinqdemi}, we deduce that
            \begin{align}\label{eq:esti-reg-infinity}
                \|\nabla u_{\rm reg}\|_{L^\infty(\Omega)} \leq C \|u_{\rm reg}\|_{H^{5/2}(\Omega)} \lesssim 1.
            \end{align}
            \end{itemize} 












            Substituting these estimates into the integrals, we obtain
            \begin{align}
                |I_{F,1}| &\lesssim \rho^{\lambda_1-1} \int_0^{h_z}\int_0^h e^{-\tau\widetilde{a} r} dr dz \lesssim \rho^{\lambda_1-1}h_z \frac{1-e^{-\tau\widetilde{a} h}}{\tau \widetilde{a}} \lesssim \rho^{\lambda_1-1}h_z \tau^{-1} ,\label{eq:esti-F1}\\
                |I_{F,4}| &\lesssim \rho^{-\widetilde{\mu_2}} \int_0^{h_z}\int_0^h r^{\widetilde{\mu_2}-1} e^{-\tau\widetilde{a} r} dr dz\lesssim \rho^{-\widetilde{\mu_2}} h_z \int_0^{+\infty} r^{\widetilde{\mu_2}-1} e^{-\tau\widetilde{a} r} dr  \nonumber \\
                &\lesssim \rho^{-\widetilde{\mu_2}}h_z (\tau\widetilde{a})^{-\widetilde{\mu_2}}\Gamma(\widetilde{\mu_2})\lesssim \rho^{-\widetilde{\mu_2}}h_z \tau^{-\widetilde{\mu_2}},\label{eq:esti-F4}\\
                |I_{F,5}| &\lesssim h_z \frac{1-e^{-\tau\widetilde{a} h}}{\tau \widetilde{a}} \lesssim h_z \tau^{-1}.\label{eq:esti-F5}
            \end{align}

            The claim follows by collecting the estimates \eqref{eq:esti-F2-infty}, \eqref{eq:esti-F2-c}, \eqref{eq:esti-F3}, \eqref{eq:esti-F1}, \eqref{eq:esti-F4} and \eqref{eq:esti-F5}.

\label{prop:upperbound}
            For $\tau>0$ large enough, the following estimate holds,
            \begin{align*}
                &\left|\int_{S^e \cup S^i\cup A_{\pm}} \left(u_0\partial_\nu (u-u')-(u-u')\partial_\nu u_0\right)d\sigma\right|\\
                &\lesssim h^{-1}\tau^{-2}+\rho^{-\mu_1}\tau^{-(\mu_1+1)}+h_z e^{-\tau \widetilde{b} h} (h^{\mu_1}\rho^{-\mu_1}+1+h\tau)\\
                &\quad +h h_z \left(\|\nabla(u-u')\|_{L^\infty(S^e)}+\tau\|u-u'\|_{L^\infty(S^e)}\right).
            \end{align*}

First, we estimate the integrals on the upper and lower faces $A_\pm$. The normal vectors on these faces are parallel to the $z$-axis. Therefore, $\partial_\nu u_0=\partial_z u_0=0$ on these regions, and hence
            \begin{align*}
                \int_{A_\pm} (u-u')\partial_\nu u_0 d\sigma =0.
            \end{align*}
            We now estimate $\partial_z u$ and $\partial_z u'$ on $A_\pm$. Since the region $\widetilde{\Omega}$ is at distance at least $h$ from the polyhedron $D'$, interior elliptic regularity implies that $u'$ is analytic there. Applying the gradient estimate (e.g. Theorem 3.9 in \cite{Gilbarg-Trudinger}), we have
            \begin{align}\label{eq:esti-grad-uprime}
                \|\nabla u'\|_{L^\infty(\widetilde{\Omega})} \leq C h^{-1} \|u'\|_{L^\infty(\Omega)}\lesssim h^{-1}.
            \end{align}
            For $\nabla u$, we must account for singularities. We decompose $u$ into singular and regular parts by \zcref{th:SingDecom}, then estimate each term.
            \begin{align*}
                u=u_{\bf v}+u_{E} +u_{\rm reg}.
            \end{align*}

            Since singular exponents are ordered increasingly, it is sufficient to consider the strongest singularity. For vertex singular functions, it is straightforward that $\displaystyle |\partial_z u_{\bf v}(x)| \leq C \rho^{\lambda_1-1}$. For edge singular functions, combining \zcref{lemma:esti-grad-edge} with \eqref{eq:esti-edge-coef}, we have
            \begin{align*}
                |\partial_z u_{E}(x)| \leq C \frac{\widetilde{r}^{\mu_1-1}}{\delta(z)}\lesssim \rho^{-\mu_1}r^{\mu_1-1}.
            \end{align*}
            For the regular part, the estimate comes directly from \eqref{eq:esti-reg-infinity}. Combining those estimates, we have,
            \begin{align*}
                \|\partial_z (u-u')\|_{L^\infty(\widetilde{\Omega})} \lesssim (h^{-1} +\rho^{-\mu_1}r^{\mu_1-1}).
            \end{align*}

            Calculating the integral over $A_\pm^i$,
            \begin{align*}
                \int_{A_\pm^i}|u_0(x)| r^{\mu_1-1}d\sigma &= \int_{-a/2}^{a/2}\int_0^h e^{-\tau r\cos \theta} r^{\mu_1} dr d\theta \leq  \int_0^h\int_{-a/2}^{a/2} e^{-\tau \widetilde{a} r} r^{\mu_1} dr d\theta \\
                &\leq a \int_0^{+\infty} e^{-\tau \widetilde{a} r} r^{\mu_1} dr \leq C \tau ^{-(\mu_1+1)}\Gamma(\mu_1+1).
            \end{align*}
            So, 
            \begin{align}\label{eq:bound-Ai}
                \left|\int_{A_\pm^i} u_0 \partial_\nu(u-u')d\sigma \right|\lesssim (h^{-1}\tau^{-2}+\rho^{-\mu_1}\tau^{-(\mu_1+1)}).
            \end{align}

            To estimate the integrals on $A_\pm^e$, we split $A_\pm^e$ into two parts. Denote by $B_{\tau}$ the two-dimensional disk on $\Pi$, centered at $O$ with radius $L\tau^{-1}$. Here, $L>1$ is chosen such that $\arcsin(1/L)<(\pi-a)/4$. With this construction, we deduce that
            \begin{align*}
                (r,\theta)\in A_-^e\setminus B_{\tau} \Rightarrow L/\tau <r< h \;\; {\rm and}\;\; \theta\in (a/2,(\pi+a)/4)\cup (-(\pi+a)/4,-a/2).
            \end{align*}
            Introducing $\widetilde{\beta}:=\cos(\frac{\pi+a}{4})>0$, we have $u_0(r,\theta,z)\leq e^{-\tau \widetilde{\beta} r}$ on $A_-^e\setminus B_{\tau}$. We now compute
            \begin{align*}
                \int_{A_-^e\cap B_{\tau}} |u_0(x)|r^{\mu_1-1} d\sigma &\leq e\int_{B_{\tau}} r^{\mu_1-1} d\sigma= 2\pi e \int_0^{L\tau^{-1}} r^{\mu_1} dr = \frac{2\pi e}{\mu_1+1} (L\tau^{-1})^{\mu_1+1}\\
                &\leq C\tau^{-(\mu_1+1)},\\
                \int_{A_-^e\setminus B_{\tau}} |u_0(x)|r^{\mu_1-1} d\sigma &\leq 2\int_{a/2}^{(\pi+a)/4} \int_{L\tau^{-1}}^h r^{\mu_1} e^{-\tau \widetilde{\beta} r} dr d\theta \leq C \int_{0}^{+\infty} r^{\mu_1} e^{-\tau \widetilde{\beta} r} dr \\
                &\leq C \tau^{-(\mu_1+1)}\Gamma(\mu_1+1).
            \end{align*}
            Hence, it follows that
            \begin{align}\label{eq:bound-Ae}
                \left|\int_{A_\pm^e} u_0 \partial_\nu (u-u')d\sigma\right|\lesssim h^{-1}\tau^{-2}+\rho^{-\mu_1}\tau^{-(\mu_1+1)}.
            \end{align}








            Next, we estimate the integrals on the inner lateral face $S^i$. One readily checks that $|u_0(x)|\leq e^{-\tau\widetilde{b}h}$ on $S^i$, with $\widetilde{b}=\cos((\pi+a)/4)>0$, once the following condition is satisfied:
            \begin{align}\label{eq:tau0}
                \tau\geq \tau_0=\frac{1}{h\sin((\pi-a)/4)}.
            \end{align}
            We assume this condition throughout the remainder of the proof. Then,
            \begin{align*}
                &\left|\int_{S^i} u_0 \partial_\nu (u-u')-(u-u')\partial_\nu u_0 d\sigma\right| \leq \left(\|\partial_\nu(u-u')\|_{L^\infty(S^i)} + \tau\|u-u'\|_{L^\infty(S^i)}\right)|S^i| e^{-\tau \widetilde{b} h}.
            \end{align*}
            The quantity $\|u-u'\|_{L^\infty(S^i)}$ can be estimated by H\"older norms that depend only on {\it a priori} data. For $\|\partial_\nu(u-u')\|_{L^\infty(S^i)}$, we apply \zcref{lemma:esti-grad-edge} to obtain $\|\partial_\nu u\|_{L^\infty(S^i)}\lesssim h^{\mu_1-1}\rho^{-\mu_1}$, and we use \eqref{eq:esti-grad-uprime} for $\nabla u'$. Consequently, we obtain the following estimate for the integrals on $S^i$:
            \begin{align}\label{eq:bound-Si}
                \left|\int_{S^i} u_0 \partial_\nu (u-u')-(u-u')\partial_\nu u_0 d\sigma\right|\lesssim hh_z e^{-\tau \widetilde{b} h} (h^{\mu_1-1}\rho^{-\mu_1}+h^{-1}+\tau).
            \end{align}

            Finally, we estimate the integrals on the lateral face $S^e$. Since we use propagation of smallness to estimate $u-u'$ and $\nabla(u-u')$ on $S^e$, the following bounds are obtained by straightforward calculations:
            \begin{align}\label{eq:bound-Se}
                &\left|\int_{S^e} u_0 \partial_\nu (u-u')- (u-u')\partial_\nu u_0 d\sigma\right| \nonumber \\
                 &\leq |S^e|\left(\|u_0\|_{L^\infty(S^e)}\|\nabla (u-u')\|_{L^\infty(S^e)} +\|\nabla u_0\|_{L^\infty(S^e)}\|(u-u')\|_{L^\infty(S^e)}\right)  \nonumber \\
                &\lesssim h h_z \left(\|\nabla(u-u')\|_{L^\infty(S^e)}+\tau\|u-u'\|_{L^\infty(S^e)}\right).
            \end{align}
            The proof is complete by collecting the results \eqref{eq:bound-Ai}, \eqref{eq:bound-Ae}, \eqref{eq:bound-Si}, and \eqref{eq:bound-Se}.

We apply the integral identity \eqref{eq:int-id} with the CGO solution $u_0$ constructed in (\ref {eq:CGO}). The left-hand side of \eqref{eq:int-id} is estimated using \zcref{prop:lowerbound}, and the right-hand side is estimated using \zcref{prop:upperbound}. Collecting these estimates, we obtain
            \begin{align*}
                \rho^{\lambda_1+\varepsilon_*-\mu_1} h_z \tau^{-\mu_1} &\lesssim \rho^{\lambda_1-1}h_z\tau^{-1} + (\rho+h_z)^{1-\mu_1}\tau^{-\mu_1} e^{-\frac{\tau \widetilde{a} h}{2}}\\
                & \quad + \rho^{-(s-\mu_1-1/2)}h_z \tau^{-(s-1/2)} + \rho^{-\widetilde{\mu_2}}h_z\tau^{-\widetilde{\mu_2}} + h_z\tau^{-1}\\
                & \quad + h^{-1}\tau^{-2}+\rho^{-\mu_1}\tau^{-(\mu_1+1)}+h_z e^{-\tau \widetilde{b} h} (h^{\mu_1}\rho^{-\mu_1}+1+h\tau)\\
                &\quad +h h_z \left(\|\nabla(u-u')\|_{L^\infty(S^e)}+\tau\|u-u'\|_{L^\infty(S^e)}\right).
            \end{align*}
            To estimate $\|u-u'\|_{L^\infty(S^e)}$ and $\|\nabla(u-u')\|_{L^\infty(S^e)}$, we apply propagation of smallness from \zcref{prop:propa-small}. Introduce the notation
            \begin{align*}
                \zeta(\varepsilon):=(\ln |\ln \varepsilon|)^{-\alpha}.
            \end{align*}
            Noting that the common H\"older norm $T$ depends only on {\it a priori} data and that the surface $S^e$ has a distance $1/\tau$ to $D$, we have,
            \begin{align*}
                \|u-u'\|_{L^\infty(S^e)} &\lesssim \zeta(\varepsilon),\\
                \|\nabla(u-u')\|_{L^\infty(S^e)} &\lesssim \tau \zeta(\varepsilon).
            \end{align*}
            Recall that $\rho,h$, and $h_z$ must satisfy the constraints \eqref{eq:constraint1},\eqref{eq:constraint2} and \eqref{eq:constraint3}, also that $D'$ is at distance at least $h$ from $\widetilde{\Omega}$. Thus, we choose
            \begin{align*}
                h_z=h,\quad \rho=\frac{h}{\ell},\quad h=\min\left\lbrace C_{\varepsilon_*}\left(1+\frac{1}{\ell}\right)^{-1} ,\frac{\ell^2}{2\ell+1},\;\frac{1}{2}d_H(D,D')\right\rbrace.
            \end{align*}
            Then the estimate becomes
            \begin{align*}
                h^{\lambda_1+\varepsilon_*-\mu_1+1} \tau^{-\mu_1} &\lesssim h^{\lambda_1}\tau^{-1} + h^{1-\mu_1}\tau^{-\mu_1} e^{-\frac{\tau \widetilde{a} h}{2}} + h^{3/2-s+\mu_1} \tau^{-(s-1/2)} + h^{1-\widetilde{\mu_2}}\tau^{-\widetilde{\mu_2}} + h\tau^{-1}\\
                & \quad + h^{-1}\tau^{-2}+h^{-\mu_1}\tau^{-\mu_1-1}+h e^{-\tau \widetilde{b} h} (1+h\tau) +h^2 \tau \zeta(\varepsilon).
            \end{align*}
            Next, we use the usual inequalities $e^{-x}\leq x^{-1}$ and $e^{-x}\leq x^{-2}$ for all $x>0$ to deduce that
            \begin{align*}
                h^{\lambda_1+\varepsilon_*-\mu_1+1} \tau^{-\mu_1} &\lesssim h^{\lambda_1}\tau^{-1} + h^{-\mu_1}\tau^{-\mu_1-1} + h^{3/2-s+\mu_1} \tau^{-(s-1/2)} + h^{1-\widetilde{\mu_2}}\tau^{-\widetilde{\mu_2}} + h\tau^{-1}\\
                & \quad + h^{-1}\tau^{-2}+h^{-\mu_1}\tau^{-\mu_1-1}+\tau^{-1} +h^2 \tau \zeta(\varepsilon).
            \end{align*}
            Recall the estimates on singular exponents: $0<\lambda_1<s-1/2$, $0<\mu_1<1$, and $3/2\leq s <\mu_1+1$. Combining these with $\tau\geq 1$ and $h\leq 1$, we deduce that
            \begin{align*}
                h^{\lambda_1+\varepsilon_*-\mu_1+1} \tau^{-\mu_1} &\lesssim h^{-1}\tau^{-1}+  h^{1-\widetilde{\mu_2}}\tau^{-\widetilde{\mu_2}}+h^2 \tau \zeta(\varepsilon).
            \end{align*}
            Recalling that $s=3/2+\epsilon$ with $0<\epsilon<\mu_1-1/2$ and using the definition of $\widetilde{\mu_2}$, we distinguish the following two cases.
            \begin{itemize}
                \item If $s-\mu_2\geq 1/2$, then $-\widetilde{\mu_2}=-\mu_2$ and $1-\widetilde{\mu_2}=1-\mu_2\geq 3/2-s=\epsilon>-1/2$.
                \item If $s-\mu_2< 1/2$, then $-\widetilde{\mu_2}=1/2-s=-1-\epsilon <-1$ and $1-\widetilde{\mu_2}=-\epsilon >-1/2$.
            \end{itemize}
            Taking into account that $\mu_2>1$, the estimate becomes
            \begin{align*}
                h^{\lambda_1+\varepsilon_*-\mu_1+1} \tau^{-\mu_1} &\lesssim h^{-1}\tau^{-1}+h^2 \tau \zeta(\varepsilon).
            \end{align*}
            By minimizing the right-hand side with respect to $\tau$, we choose
            \begin{align}
                \tau=\tau_e:=\left(h^3\zeta(\varepsilon)\right)^{-\frac{1}{2}}.
            \end{align}
            For $\varepsilon$ sufficiently small, one can verify that $\tau_e\geq \tau_0$, where $\tau_0$ is given in \eqref{eq:tau0}.

            Substituting this choice into the estimate and solving for $h$, we obtain
            \begin{align*}
                h \lesssim \zeta(\varepsilon)^{\frac{1}{2(\lambda_1+\varepsilon_*)+\mu_1+1}}\leq \zeta(\varepsilon)^{\frac{1}{3\lambda_1+\mu_1+1}},                                                   
            \end{align*}
            where the last inequality holds by choosing $\varepsilon_*<\lambda_1/2$.

            Finally, as $\displaystyle \zeta(\varepsilon)\underset{{\varepsilon}\rightarrow {0}}{\longrightarrow} 0$, we can deduce that for $\varepsilon$ small enough, the right-hand side above is less than both $C_{\varepsilon_*}\left(1+\frac{1}{\ell}\right)^{-1}$ and $\frac{\ell^2}{2\ell+1}$. Hence, the stability estimate \eqref{eq:stable} follows with the exponent $\kappa$ given by
            \begin{align*}
               \kappa:= \frac{-\alpha }{3\lambda_1+\mu_1+1}.
            \end{align*}
            The exponent $\kappa$ is bounded below by a constant depending only on {\it a priori} data, using $\alpha=\min\{\alpha_0,\epsilon,\lambda_1,\mu_1\}$ from \zcref{prop:propa-small} and the bounds $\mu_1\in (\frac{1}{2},1)$, $\lambda_1\in (1,\sqrt{2k})$.

            The proof is complete.

\label{lemma:esti-grad-edge}
            Let $\frac{1}{2}<\mu<s$ and let $u_{E,\mu}$ be given by \eqref{eq:edge-singular} with coefficient $\gamma\in V_{-s}^{s-\mu}(E)$. Then, in the region $\widetilde{\Omega}$, there exists a constant $C_{\phi,\mu}>0$ such that
            \begin{align}\label{eq:esti-grad-edge}
                |\nabla u_{E,\mu}(r,\theta,z)| \leq C_{\phi,\mu} \|\gamma\|_{V_{-s}^{s-\mu}(E)}\frac{r^{\widetilde{\mu}-1}}{\rho^{\widetilde{\mu}}}.
            \end{align}
            Here, $\rho$ denotes the distance from the point $(r,\theta,z)$ to its closest endpoint of $E$. Also, $\widetilde{\mu}=\mu$ if $s-\mu\geq 1/2$ and $\widetilde{\mu}=s-1/2$ if $s-\mu<1/2$.

By a change of variables stretching $E$ into $2.4$ and the embedding \eqref{eq:embedding-weighted}, we have $\widetilde{\gamma}\in H^{s-\mu}(2.4)$. We compute $\partial_z u_{E,\mu}$ via the chain rule:
            \begin{align*}
                \frac{\partial}{\partial z}u_{E,\mu}(r,\theta,z)&= \left(\frac{\partial \widetilde{z}}{\partial z}\frac{\partial}{\partial \widetilde{z}}+\frac{\partial \widetilde{r}}{\partial z}\frac{\partial}{\partial \widetilde{r}}\right) u_{E,\mu}(r,\theta,z)\\
                &= \frac{1}{\delta(z)}\left(\frac{\partial}{\partial \widetilde{z}}\mathcal{K}[\gamma]\right)\widetilde{r}^{\mu}\varphi(\theta)-\frac{\delta'(z)}{\delta(z)} \left(\widetilde{r}^{\mu+1} \frac{\partial}{\partial \widetilde{r}}\mathcal{K}[\gamma]+\mu \widetilde{r}^{\mu}\mathcal{K}[\gamma]\right) \varphi(\theta)\\
                \frac{\partial}{\partial r} u_{E,\mu}(r,\theta,z) &= \frac{\partial \widetilde{r}}{\partial r}\frac{\partial}{\partial \widetilde{r}} u_{E,\mu}(r,\theta,z)=\frac{1}{\delta(z)}\left(\frac{\partial}{\partial \widetilde{r}}\mathcal{K}[\gamma]\right)\widetilde{r}^{\mu}\varphi(\theta)+\frac{\mu}{\delta(z)} \mathcal{K}[\gamma]\widetilde{r}^{\mu-1}\varphi(\theta),\\
                \frac{1}{r} \frac{\partial}{\partial \theta} u_{E,\mu}(r,\theta,z) &= \frac{1}{\delta(z)}\mathcal{K}[\gamma]\widetilde{r}^{\mu-1}\varphi'(\theta).
            \end{align*}
            By the convolution structure of $\mathcal{K}$, we have:
            \begin{align*}
                \frac{\partial}{\partial \widetilde{z}}\mathcal{K}[\gamma](\widetilde{r},z)& = \frac{\partial}{\partial \widetilde{z}}\int_2.4 \frac{1}{\widetilde{r}}\phi(\frac{\widetilde{z}-t}{\widetilde{r}})\widetilde{\gamma}(t)dt=\frac{1}{\widetilde{r}}\int_2.4 \frac{1}{\widetilde{r}}\phi'(\frac{t}{\widetilde{r}})\widetilde{\gamma}(\widetilde{z}-t) dt,\\
                \frac{\partial}{\partial \widetilde{r}}\mathcal{K}[\gamma](\widetilde{r},z)&= -\int_2.4 \left(\frac{1}{\widetilde{r}^2}\phi(\frac{t}{\widetilde{r}})+\frac{t}{\widetilde{r}^3}\phi'(\frac{t}{\widetilde{r}})\right)\widetilde{\gamma}(\widetilde{z}-t)dt=-\frac{1}{\widetilde{r}}\int_2.4 \frac{1}{\widetilde{r}}(t\phi)'(\frac{t}{\widetilde{r}})\gamma(\widetilde{z}-t)dt.
            \end{align*}
            Note that $\phi',\;(t\phi)'\in \mathcal{S}(2.4)$. We apply the Sobolev embedding $H^{s-\mu}(2.4)\hookrightarrow L^q(2.4)$ with $\frac{1}{q}=\frac{1}{2}-(s-\mu)$ if $s-\mu<1/2$ and $q=\infty$ if $s-\mu\geq 1/2$.
            \begin{itemize}
                \item Case $s-\mu <1/2$. Denoting by $q'$ the conjugate exponent of $q$, it follows from H\"older's inequality that
                \begin{align*}
                    \left|\mathcal{K}[\gamma](\widetilde{r},z)\right| &\leq \widetilde{r}^{-1/q} \|\phi\|_{L^{q'}(2.4)} \|\widetilde{\gamma}\|_{L^q(2.4)}=\widetilde{r}^{(s-\mu)-1/2} \|\phi\|_{L^{q'}(2.4)} \|\widetilde{\gamma}\|_{L^q(2.4)},\\
                    \left|\frac{\partial}{\partial \widetilde{z}}\mathcal{K}[\gamma](\widetilde{r},z)\right| &\leq \widetilde{r}^{(s-\mu)-3/2} \|\phi'\|_{L^{q'}(2.4)} \|\widetilde{\gamma}\|_{L^q(2.4)},\\
                    \left|\frac{\partial}{\partial \widetilde{r}}\mathcal{K}[\gamma](\widetilde{r},z)\right| &\leq \widetilde{r}^{(s-\mu)-3/2} \|(t\phi)'\|_{L^{q'}(2.4)} \|\widetilde{\gamma}\|_{L^q(2.4)}.
                \end{align*}
                \item Case $s-\mu\geq 1/2$. Using Young's inequality, we have
                \begin{align*}
                    |\mathcal{K}[\gamma](\widetilde{r},z)| &\leq \|\phi\|_{L^1(2.4)} \|\widetilde{\gamma}\|_{L^\infty(2.4)},\\
                    \left|\frac{\partial}{\partial \widetilde{z}}\mathcal{K}[\gamma](\widetilde{r},z)\right| &\leq \widetilde{r}^{-1} \|\phi'\|_{L^1(2.4)} \|\widetilde{\gamma}\|_{L^\infty(2.4)},\\
                    \left|\frac{\partial}{\partial \widetilde{r}}\mathcal{K}[\gamma](\widetilde{r},z)\right| &\leq \widetilde{r}^{-1} \|(t\phi)'\|_{L^1(2.4)} \|\widetilde{\gamma}\|_{L^\infty(2.4)}.
                \end{align*}
            \end{itemize}
            Define $\widetilde{\mu}:=\mu$ if $s-\mu\geq 1/2$ and $\widetilde{\mu}=s-1/2$ if $s-\mu<1/2$. Substituting these estimates into the expressions for derivatives of $u_{E,\mu}$, we obtain
            \begin{align*}
                \left|\frac{\partial}{\partial z} u_{E,\mu}(r,\theta,z)\right| &\leq \|\widetilde{\gamma}\|_{L^q(2.4)} \left(\frac{\widetilde{r}^{\widetilde{\mu}-1}}{\delta(z)} \|\phi'\|_{L^{q'}(2.4)} + \frac{|\delta'(z)| \widetilde{r}^{\widetilde{\mu}}}{\delta(z)}(\|(t\phi)'\|_{L^{q'}(2.4)}+\mu \|\phi\|_{L^{q'}(2.4)})\right).
            \end{align*}
            The same estimate holds for $\frac{\partial}{\partial r} u_{E,\mu}$.

            Note that the cut-off function $\eta$ and its support $\ell$ satisfy $\ell \leq 1/2$ and $\eta(\widetilde{r})=0$ if $\widetilde{r}\geq 2\ell$. Hence we may assume $\widetilde{r}\leq 1$. Also, $\delta$ is equivalent to the distance to the endpoints of $E$, which implies $\delta(z)\geq C_{\delta}\rho$ for some constant $C_\delta>0$. Then the estimates become
            \begin{align*}
                &\left|\frac{\partial}{\partial z} u_{E,\mu}(r,\theta,z)\right|,\; \left|\frac{\partial}{\partial r} u_{E,\mu}(r,\theta,z)\right|\\
                 &\leq \|\widetilde{\gamma}\|_{L^q(2.4)} C_\delta^{-\widetilde{\mu}}\left( \|\phi'\|_{L^{q'}(2.4)} + |\delta'(z)|(\|(t\phi)'\|_{L^{q'}(2.4)}+\mu \|\phi\|_{L^{q'}(2.4)})\right)\frac{r^{\widetilde{\mu}-1}}{\rho^{\widetilde{\mu}}},\\
                 & \frac{1}{r} \left|\frac{\partial}{\partial \theta} u_{E,\mu}(r,\theta,z)\right| \leq \mu\|\widetilde{\gamma}\|_{L^q(2.4)} C_\delta^{-\widetilde{\mu}} \|\phi\|_{L^{q'}(2.4)}\frac{r^{\widetilde{\mu}-1}}{\rho^{\widetilde{\mu}}}.
            \end{align*}            

            Thus, the claim follows by combining these estimates with \eqref{eq:embedding-weighted}.

\label{lemma:K-gamma}
            Let $1/2<\mu$ and let $\mu+1/2<s<\mu+1$. Then, there exists a constant $C'_{\phi,\mu}>0$ such that
            \begin{align*}
               \forall z\in E,\; \widetilde{r}>0,\quad |\mathcal{K}[\gamma](\widetilde{r},z)-\gamma(z)|\leq C'_{\phi,\mu} \widetilde{r}^{s-\mu-1/2}\|\gamma\|_{V_{-s}^{s-\mu}(E)}.
            \end{align*}

Using the fact $\displaystyle \int_2.4 \phi(t)dt=1$, we have 
            \begin{align*}
                \mathcal{K}[\gamma](\widetilde{r},z)-\widetilde{\gamma}(\widetilde{z})=\int_2.4 \frac{1}{\widetilde{r}} \phi(\frac{t}{\widetilde{r}})(\widetilde{\gamma}(\widetilde{z}-t)-\widetilde{\gamma}(\widetilde{z})) dt.
            \end{align*}
            We split this integral into two parts, one for $|t|\leq \widetilde{r}$ and the other for $|t|>\widetilde{r}$.

            Since $s-\mu>1/2$ and $\widetilde{g}\in H^{s-\mu}(2.4)$, it follows from Sobolev embedding that $\widetilde{\gamma}\in \mathcal{C}^{s-\mu-1/2}(2.4)$, and for some constant $C>0$ that
            \begin{align*}
                    \forall x,y\in2.4,\quad |\widetilde{\gamma}(x)-\widetilde{\gamma}(y)| &\leq C \|\widetilde{\gamma}\|_{H^{s-\mu}(2.4)}|x-y|^{s-\mu-1/2}.
            \end{align*}
            Then, we can estimate the first part of the integral as follows,
            \begin{align*}
                \left|\int_{|t|\leq \widetilde{r}} \frac{1}{\widetilde{r}} \phi\left(\frac{t}{\widetilde{r}}\right) (\widetilde{\gamma}(\widetilde{z}-t)-\widetilde{\gamma}(\widetilde{z})) dt \right| &\leq C\|\widetilde{\gamma}\|_{H^{s-\mu}(2.4)}\widetilde{r}^{s-\mu-1/2}\|\phi\|_{L^1(2.4)}.
            \end{align*}
            For the second part, since $\phi$ is rapidly decreasing, there exists $C'>0$ such that $\displaystyle |x^2\phi(x)| \leq C'$. Then, we can estimate the second part of the integral as follows,
            \begin{align*}
                \left|\int_{|t|>\widetilde{r}} \frac{1}{\widetilde{r}} \phi\left(\frac{t}{\widetilde{r}}\right) (\widetilde{\gamma}(\widetilde{z}-t)-\widetilde{\gamma}(\widetilde{z})) dt \right| &\leq 2C'\|\widetilde{\gamma}\|_{L^\infty(2.4)}\int_{\widetilde{r}}^{+\infty} \frac{\widetilde{r}^2}{t^2} dt \leq 2C'\|\widetilde{\gamma}\|_{L^\infty(2.4)}\widetilde{r}.
            \end{align*}
            The claim follows by combining these estimates with the embedding \eqref{eq:embedding-weighted}.
